```ts
import type { EventBus } from '../../services/event-bus.js';
import type { MemoryEvent, MemoryEventType, MemoryPressureLevel } from './types.js';

export function emitMemoryEvent(
  eventBus: EventBus,
  type: MemoryEventType,
  payload: { level: MemoryPressureLevel; usagePercent: number },
): void {
  const event: MemoryEvent = { type, ...payload, timestamp: Date.now() };
  eventBus.emit('memory', event);
}
```

